INTRO = "Safe inside a hotel suite, Xin Huimei trusts Chun Yuqiao with her family secret: the little boy is her father's son from an affair whom she took in to shield her parents' marriage from public disgrace. Listen to Xin Huimei and Chun Yuqiao in Mandarin first."
OPENER = "Now let's go through it line by line with the English translation."
STORY = [('xin_huimei', '应该是我感谢你，愿意相信我。', 'I should be the one thanking you for choosing to believe in me.', [(301, '应该是我感谢你'), (302, '愿意相信我')], ''), ('chun_yuqiao', '当然要相信你了。那现在能告诉我了吗？', 'Of course I trust you. Can you tell me what happened now?', [(303, '当然要相信你了'), (304, '那现在能告诉我了吗')], ''), ('xin_huimei', '他叫小允，是我父亲的儿子。我从来都不知道我父亲会出轨。', "His name is little Yun — he is my father's son. I never imagined my father would have an affair.", [(305, '他叫小允'), (306, '是我父亲的儿子'), (308, '我从来都不知道我父亲会出轨')], ''), ('xin_huimei', '我父亲答应不再和那个女人联系，才保住了他们的婚姻，但他确实是我的亲弟弟。', 'My father promised never to contact that woman again to save their marriage, yet the boy is truly my half-brother.', [(311, '我父亲答应不再和那个女人联系'), (312, '才保住了他们的婚姻'), (313, '但他确实是我的亲弟弟')], ''), ('xin_huimei', '我给了那个女人一笔钱，她就扔下小允出国去了，我不能丢下他不管。', "I gave that woman a sum of money and she abandoned him to go abroad; I couldn't leave him behind.", [(314, '我给了那个女人一笔钱'), (315, '扔下小允出国去了'), (316, '我不能丢下他不管')], ''), ('xin_huimei', '我也不能让父母的事情曝光在大众的视线里面，我必须得保护他。', 'Nor can I let their private pain be exposed to the public eye — I have to protect him.', [(317, '也不能让父母的事情'), (318, '曝光在大众的视线里面'), (319, '我必须得保护他')], ''), ('chun_yuqiao', '你真的很坚强，比我想象的还要坚强。', 'You really are strong — even stronger than I imagined.', [(320, '你真的很坚强'), (321, '比我想象的还要坚强')], ''), ('chun_yuqiao', '但是现在孩子已经曝光了，压力也很快就会来。', 'Still, now that the child has been photographed, intense pressure will arrive any moment.', [(322, '但是现在孩子已经曝光了'), (324, '压力也很快就会来')], ''), ('chun_yuqiao', '就我之前处理这样问题的经验来看，娱乐圈里面公布恋情是最快的办法。', 'From my past experience handling crises like this in show business, announcing a relationship is the fastest shield.', [(356, '就我之前处理'), (357, '经验来看'), (360, '娱乐圈里面'), (361, '恋爱是最快的')], ''), ('xin_huimei', '谢谢你今天帮我，但是如果你再继续说下去的话，我就要带着小允走出去了。', 'Thank you for helping me today, yet if you keep suggesting a fake romance, I will take my brother and walk out.', [(364, '谢谢你今天帮我'), (365, '但是如果你再继续说下去的话'), (366, '我就要带着小允'), (367, '从这个房间走出去')], ''), ('xin_huimei', '只是我的性格，我只会为了恋爱而恋爱，只会跟自己真正喜欢的人在一起。', 'That is simply who I am: I only date for love itself, and I will only be with someone I truly love.', [(370, '只是我的性格'), (371, '我只会为了恋爱而恋爱'), (372, '只会跟自己'), (373, '真正喜欢的人在一起')], ''), ('chun_yuqiao', '什么也别说了，你只需要清楚你心里真正想要的是什么。', 'Say no more right now — all you need to know is what your own heart truly wants.', [(375, '什么也别说了'), (376, '你只需要清楚'), (377, '你心里真正想要的是什么')], '')]
WALK = [(0, None, "'I should be the one thanking you for choosing to believe in me.'"), (1, None, "'Of course I trust you. Can you tell me what happened now?'"), (2, None, '"His name is little Yun — he is my father\'s son. I never imagined my father would have an affair."'), (3, None, "'My father promised never to contact that woman again to save their marriage, yet the boy is truly my half-brother.'"), (4, None, '"I gave that woman a sum of money and she abandoned him to go abroad; I couldn\'t leave him behind."'), (5, None, "'Nor can I let their private pain be exposed to the public eye — I have to protect him.'"), (6, None, "'You really are strong — even stronger than I imagined.'"), (7, None, "'Still, now that the child has been photographed, intense pressure will arrive any moment.'"), (8, None, "'From my past experience handling crises like this in show business, announcing a relationship is the fastest shield.'"), (9, None, "'Thank you for helping me today, yet if you keep suggesting a fake romance, I will take my brother and walk out.'"), (10, None, "'That is simply who I am: I only date for love itself, and I will only be with someone I truly love.'"), (11, None, "'Say no more right now — all you need to know is what your own heart truly wants.'")]
